import {load,save} from './storage.js';
const $=s=>document.querySelector(s), ID=()=>globalThis.crypto?.randomUUID?.()||`p${Date.now()}${Math.random().toString(36).slice(2)}`;
const now=()=>new Date().toISOString(), esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const icons={luggage:'<rect x="4" y="8" width="16" height="13" rx="3"/><path d="M9 8V6a3 3 0 0 1 6 0v2M4 14h16M12 14v3"/>',home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m1 4a5 5 0 0 1 4 5"/>',package:'<path d="m12 2 9 5v10l-9 5-9-5V7zM3 7l9 5 9-5M12 12v10"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="m9 18 6-6-6-6"/>',back:'<path d="m15 18-6-6 6-6"/>',check:'<path d="m4 12 5 5 11-11"/>','check-circle':'<circle cx="12" cy="12" r="9"/><path d="m7 12 3 3 7-7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',plane:'<path d="m21 2-8 20-3-8-8-3zM10 14l11-12"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',moon:'<path d="M20 16A9 9 0 0 1 8 4a9 9 0 1 0 12 12"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m10 2-1 3-3 1-3-1-2 4 3 2v3l-3 2 2 4 3-1 3 1 1 3h4l1-3 3-1 3 1 2-4-3-2v-3l3-2-2-4-3 1-3-1-1-3z"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v13H3z"/><circle cx="12" cy="13" r="4"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="2"/><path d="m21 16-6-5-9 10"/>',folder:'<path d="M3 6h7l2 3h9v11H3z"/>',backpack:'<rect x="5" y="7" width="14" height="15" rx="4"/><path d="M9 7V5a3 3 0 0 1 6 0v2M5 13h14M8 13v5h8v-5"/>',edit:'<path d="m3 17 12-12 4 4-12 12-5 1zM14 6l3-3 4 4-3 3"/>',trash:'<path d="M4 7h16M9 7V4h6v3m-9 0 1 14h10l1-14"/>',copy:'<rect x="7" y="7" width="14" height="14" rx="2"/><path d="M4 17H3V3h14v1"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1"/>',layers:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',map:'<path d="M3 5 9 3l6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16"/>',alert:'<path d="m12 3 10 18H2zM12 9v5m0 3v1"/>','x':'<path d="M5 5l14 14M19 5 5 19"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',gift:'<rect x="3" y="10" width="18" height="11" rx="2"/><path d="M12 10v11M2 7h20v3H2zM12 7C6-1 2 6 7 7m5 0c6-8 10-1 5 0"/>',refresh:'<path d="M20 6v5h-5M4 18v-5h5M5 10a8 8 0 0 1 14-4l1 5M4 13l1 5a8 8 0 0 0 14-4"/>',locate:'<circle cx="12" cy="11" r="8"/><circle cx="12" cy="11" r="3"/><path d="M12 3V1M12 19v4M4 11H1M20 11h3"/>',bell:'<path d="M6 9a6 6 0 0 1 12 0v5l2 3H4l2-3zM10 20h4"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="2.5"/>',box:'<rect x="3" y="3" width="18" height="18" rx="3"/>'};
const ic=(n,cl='')=>`<svg class="${cl}" viewBox="0 0 24 24" stroke="currentColor" fill="none" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" aria-hidden="true">${icons[n]||icons.box}</svg>`;
const initial=()=>({schemaVersion:4,theme:'dark',people:[],catalog:[],sets:[],bagTemplates:[],trips:[],bags:[],bagPositions:[],items:[],legs:[],events:[],createdAt:now(),updatedAt:now()});
let s=initial(),view={page:'overview',tripId:null,tab:'packing',leg:'out',term:'',searchTerm:'',searchScope:'current',selectedRoot:null},writeQueue=Promise.resolve(),toastTimeout;
const trip=id=>s.trips.find(t=>t.id===id), root=t=>{while(t?.parentId)t=trip(t.parentId);return t},rootId=t=>root(t)?.id;
const children=id=>s.trips.filter(t=>t.parentId===id),person=id=>s.people.find(p=>p.id===id),pname=id=>person(id)?.name||'Ingen eier';
const bag=id=>s.bags.find(b=>b.id===id),rBags=t=>s.bags.filter(b=>b.rootId===rootId(t)),inventory=t=>s.items.filter(i=>i.rootId===rootId(t));
const entries=(t,leg)=>s.legs.filter(r=>r.tripId===t.id&&r.leg===leg),entry=(t,leg,itemId)=>s.legs.find(r=>r.tripId===t.id&&r.leg===leg&&r.itemId===itemId);
const placement=(t,leg,bid)=>s.bagPositions.find(p=>p.tripId===t.id&&p.leg===leg&&p.bagId===bid);
const tripBags=(t,leg)=>s.bagPositions.filter(p=>p.tripId===t.id&&p.leg===leg).map(p=>bag(p.bagId)).filter(Boolean);
const bagPath=(t,leg,bid)=>{if(!bid)return 'Uten bagasje';const path=[],used=new Set();let current=bid;while(current&&!used.has(current)){used.add(current);const b=bag(current);if(!b)break;path.unshift(b.name);current=placement(t,leg,current)?.parentBagId||null;}return path.join(' › ')||'Uten bagasje';};
const safeImg=v=>typeof v==='string'&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(v);
const cover=t=>safeImg(t?.cover)?t.cover:(t?.parentId?cover(trip(t.parentId)):null);
const photoAttrs=t=>cover(t)?`<img class="hero-photo" src="${cover(t)}" alt="Forsidebilde for ${esc(t.name)}" style="object-position:center ${Number(t.coverY??50)}%">`:'';
const portrait=p=>safeImg(p?.photo)?`<img class="avatar-photo" src="${p.photo}" alt="">`:`<div class="avatar">${esc((p?.name||'?').slice(0,2).toUpperCase())}</div>`;
const itemPhoto=i=>safeImg(i?.photo)?i.photo:(safeImg(s.catalog.find(c=>c.id===i?.sourceCatalogId)?.photo)?s.catalog.find(c=>c.id===i.sourceCatalogId).photo:null);
const itemThumb=i=>itemPhoto(i)?`<img class="item-image" src="${itemPhoto(i)}" alt="">`:`<span class="item-placeholder">${ic('package')}</span>`;
const thumb=t=>cover(t)?`<img class="thumb" src="${cover(t)}" alt="">`:`<div class="thumb">${ic(t.parentId?'map':'luggage')}</div>`;
const dateStr=d=>d?new Date(d+'T12:00:00').toLocaleDateString('nb-NO',{day:'numeric',month:'short',year:'numeric'}):'Ingen dato';
const period=t=>[t.start,t.end].filter(Boolean).map(dateStr).join(' – ')||'Dato ikke satt';
const dayDiff=d=>d?Math.ceil((new Date(d+'T00:00:00')-new Date(new Date().toDateString()))/86400000):null;
const stage=t=>t.phase==='done'?'Avsluttet':t.phase==='ongoing'?'Pågår':t.phase==='return'?'Hjemreise':'Planlegging';
const stageTag=t=>`<span class="tag ${t.phase==='ongoing'?'teal':t.phase==='return'?'warning':''}">${stage(t)}</span>`;
const pct=(n,d)=>d?Math.round(100*n/d):0;
const stats=(t,leg)=>{const e=entries(t,leg);return {done:e.reduce((a,x)=>a+Math.min(x.qty,x.packedQty||0),0),total:e.reduce((a,x)=>a+x.qty,0)}};
const pbar=(done,total)=>`<div class="progress" role="progressbar" aria-valuenow="${pct(done,total)}" aria-valuemin="0" aria-valuemax="100"><div style="width:${pct(done,total)}%"></div></div>`;
const btn=(label,action,ico='plus',variant='',extra='')=>`<button class="btn ${variant}" type="button" data-action="${action}" ${extra}>${ic(ico)} ${label}</button>`;
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=`toast visible${error?' error':''}`;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.className='toast',4000);}
function persist(){s.updatedAt=now();const snapshot=structuredClone(s);writeQueue=writeQueue.catch(()=>{}).then(()=>save(snapshot)).then(()=>{$('#save-pip')?.classList.remove('error')}).catch(e=>{$('#save-pip')?.classList.add('error');toast('Kunne ikke lagre. Ta sikkerhetskopi: '+e.message,true)});}
const setTheme=theme=>{s.theme=theme;document.documentElement.dataset.theme=theme;document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#101A2B':'#EFF4FC';};
function navigation(){
 const nav=[['overview','Oversikt','home'],['trips','Turer','luggage'],['people','Deltakere','users'],['things','Mine ting','package'],['settings','Mer','menu']];
 const brand=`<span class="word-codex">Codex</span> <span class="word-packit">Packit</span>`;
 $('#sidebar').innerHTML=`<div class="brand"><div class="mark">${ic('luggage')}</div><div class="brand-copy"><strong>${brand}</strong><small>POLAR BLUE · CODEX NORD</small></div></div><div class="side-nav">${nav.map(([id,l,i])=>`<button class="nav-link ${view.page===id||(view.page==='trip'&&id==='trips')?'active':''}" data-action="navigate" data-page="${id}">${ic(i)}<span>${l}</span></button>`).join('')}</div><div class="sidebar-bottom"><button class="nav-link" data-action="navigate" data-page="search">${ic('search')}<span>Finn ting</span></button><div class="sidebar-version">PACKIT · TEST v0.4</div></div>`;
 $('#mobile-nav').innerHTML=nav.map(([id,l,i])=>`<button class="${view.page===id||(view.page==='trip'&&id==='trips')?'active':''}" data-action="navigate" data-page="${id}">${ic(i)}<span>${l}</span></button>`).join('');
 const title=view.page==='trip'?trip(view.tripId)?.name||'Tur':({overview:'Oversikt',trips:'Turer',people:'Deltakere',things:'Mine ting',settings:'Mer',search:'Finn ting'})[view.page];
 $('#header').innerHTML=`<div class="header-brand" aria-label="Codex Packit">${brand}<small>${esc(title)}</small></div><div class="header-actions"><div class="header-status"><span class="pip" id="save-pip"></span>Lagret lokalt</div><button type="button" class="icon-btn" title="Finn ting" aria-label="Finn ting" data-action="navigate" data-page="search">${ic('search')}</button><button type="button" class="icon-btn" title="Bytt tema" aria-label="Bytt tema" data-action="theme">${ic(s.theme==='dark'?'sun':'moon')}</button></div>`;
}

function render(){navigation();$('#main').innerHTML=({overview:renderOverview,trips:renderTrips,people:renderPeople,things:renderThings,settings:renderSettings,trip:renderTrip,search:renderSearch})[view.page]();}
function go(page,id){view.page=page;if(id)view.tripId=id;if(page==='trip'){view.tab='packing';view.leg='out';view.term='';}render();$('#main').scrollTo({top:0,behavior:'instant'})}
function heading(title,description='',actions=''){return `<div class="page-head"><div><div class="eyebrow">CODEX PACKIT</div><h1>${title}</h1>${description?`<p class="muted" style="margin-top:8px">${description}</p>`:''}</div><div class="actions">${actions}</div></div>`;}
const blank=(title,desc,action='')=>`<div class="empty">${ic('luggage')}<h3>${title}</h3><p>${desc}</p>${action}</div>`;
const tripRow=t=>`<div class="trip-row">${thumb(t)}<div class="grow"><h3>${esc(t.name)}</h3><small>${esc(period(t))} · ${t.participantIds?.length||0} deltakere</small></div>${stageTag(t)}<button class="row-action" aria-label="Åpne ${esc(t.name)}" data-action="open-trip" data-id="${t.id}">${ic('arrow')}</button></div>`;
function preferred(){const roots=s.trips.filter(t=>!t.parentId&&t.phase!=='done');roots.sort((a,b)=>{let aa=a.start||'9999',bb=b.start||'9999';return aa.localeCompare(bb)});return roots[0]||s.trips.find(t=>!t.parentId)||null;}
function focused(t){if(!t)return null;const today=new Date().toISOString().slice(0,10);let all=[t,...children(t.id)].filter(x=>x.phase!=='done');const sorted=all.filter(x=>x.start&&x.start>=today).sort((a,b)=>a.start.localeCompare(b.start));const ongoing=all.filter(x=>x.phase==='ongoing'||x.phase==='return').sort((a,b)=>(a.end||'9999').localeCompare(b.end||'9999'));if(t.phase==='planning'&&(!t.start||t.start>today))return t;return ongoing.find(x=>x.id!==t.id)||sorted.find(x=>x.id!==t.id)||t;}
function mainHero(t){
 const active=focused(t)||t,days=dayDiff(active.start),leg=active.phase==='return'?'return':'out',st=stats(active,leg),subcount=children(t.id).length;
 const countdown=days!==null&&days>=0?`${days} dager til ${active===t?'avreise':esc(active.name)}`:active.phase==='return'?'Hjemreisekontroll':active===t?'Reisen pågår':esc(active.name)+' pågår';
 return `<section class="hero compact-hero">${photoAttrs(t)}<span class="hero-overlay-label">HOVEDTUR</span><div class="hero-inner"><div class="eyebrow">${t.phase==='ongoing'?'AKTIV REISE':'NESTE REISE'}</div><h1>${esc(t.name)}</h1><p class="hero-desc">${esc(period(t))}${t.destination?' · '+esc(t.destination):''}</p>
 <div class="hero-stats"><div><strong>${t.participantIds?.length||0}</strong><small>Deltakere</small></div><div><strong>${tripBags(t,'out').length}</strong><small>Bagasje</small></div><div><strong>${subcount}</strong><small>Delreiser</small></div></div>
 <div class="hero-progress"><div class="progress-top"><span>${active===t?'Pakket til '+(leg==='out'?'utreise':'hjemreise'):'Neste: '+esc(active.name)}</span><strong>${st.done} / ${st.total}</strong></div>${pbar(st.done,st.total)}<div class="hero-next">${ic('clock')} ${countdown}${st.total?` · ${Math.max(0,st.total-st.done)} gjenstår`:''}</div></div>
 ${btn(st.total?'Fortsett pakking':'Åpne pakkeliste','open-trip','arrow','hero-continue',`data-id="${active.id}"`)}
 </div></section>`;
}

function renderOverview(){
 const t=preferred(),roots=s.trips.filter(x=>!x.parentId),oth=roots.filter(x=>x.id!==t?.id);
 return `${heading('Oversikt','Din neste tur og det som gjenstår.')}${t?mainHero(t):blank('Velkommen til Packit','Du har ingen turer ennå. Opprett en tur under fanen «Turer».',btn('Gå til Turer','navigate','luggage','secondary','data-page="trips"'))}${t&&children(t.id).length?`<section class="section-title"><h2>Delreiser</h2><button class="card-link" data-action="open-trip" data-id="${t.id}">Se hovedtur ›</button></section><div class="card">${children(t.id).sort((a,b)=>(a.start||'').localeCompare(b.start||'')).map(tripRow).join('')}</div>`:''}<section class="section-title"><h2>Andre turer</h2><button class="card-link" data-action="navigate" data-page="trips">Se alle ›</button></section>${oth.length?`<div class="card">${oth.slice(0,4).map(tripRow).join('')}</div>`:!t? '':`<div class="hint">Ingen andre turer registrert.</div>`}${t&&s.events.some(x=>x.rootId===t.id)?`<section class="section-title"><h2>Siste endringer</h2></section><div class="card">${s.events.filter(e=>e.rootId===t.id).slice(-3).reverse().map(logLine).join('')}</div>`:''}`;
}

function renderTrips(){const roots=s.trips.filter(t=>!t.parentId).sort((a,b)=>(b.start||'').localeCompare(a.start||''));return `${heading('Mine turer','Hovedturer med egne delreiser og pakkekontroller.',btn('Ny hovedtur','new-trip','plus'))}${roots.length?`<div class="stack">${roots.map(t=>`<div class="card"><div class="row between"><div class="row grow">${thumb(t)}<div class="grow"><h2 style="margin:0 0 5px">${esc(t.name)}</h2><div class="muted small">${esc(period(t))}</div><div style="margin-top:8px">${stageTag(t)}</div></div></div><button class="icon-btn" data-action="open-trip" data-id="${t.id}" aria-label="Åpne tur">${ic('arrow')}</button></div>${children(t.id).length?`<div class="line"></div>${children(t.id).sort((a,b)=>(a.start||'').localeCompare(b.start||'')).map(c=>`<div class="simple-row"><div class="card-icon">${ic('map')}</div><div class="grow"><strong>${esc(c.name)}</strong><div class="muted small">${esc(period(c))}</div></div><button class="row-action" data-action="open-trip" data-id="${c.id}">${ic('arrow')}</button></div>`).join('')}`:''}<div class="actions" style="margin-top:14px">${btn('Åpne tur','open-trip','arrow','secondary',`data-id="${t.id}"`)}${btn('Ny undertur','new-sub','plus','ghost',`data-id="${t.id}"`)}</div></div>`).join('')}</div>`:blank('Ingen turer ennå','Opprett en hovedtur for å begynne.',btn('Opprett tur','new-trip','plus'))}`;}
function renderTrip(){const t=trip(view.tripId);if(!t){view.page='trips';return renderTrips()}const st=stats(t,view.leg),n=children(t.id).length;const tabs=[['packing','Pakking'],['bags','Bagasje'],['subtrips','Delreiser'],['info','Turinfo']];return `<div class="actions" style="margin-bottom:14px"><button class="btn ghost small" data-action="${t.parentId?'open-trip':'navigate'}" ${t.parentId?`data-id="${t.parentId}"`:'data-page="trips"'}>${ic('back')}${t.parentId?'Til hovedtur':'Alle turer'}</button></div><section class="hero" style="min-height:230px">${photoAttrs(t)}<span class="hero-overlay-label">${t.parentId?'UNDERTUR':'HOVEDTUR'}</span><div class="hero-inner"><div class="eyebrow">${esc(stage(t))}</div><h1 style="margin-top:9px">${esc(t.name)}</h1><p class="hero-desc">${esc(period(t))}${t.destination?' · '+esc(t.destination):''}</p><div class="hero-meta"><span>${ic('users')}${t.participantIds?.length||0} deltakere</span><span>${ic('luggage')}${tripBags(t,view.leg).length} bagasjeenheter</span>${!t.parentId?`<span>${ic('map')}${n} delreiser</span>`:''}</div></div></section><div class="trip-tabs">${tabs.filter(([k])=>k!=='subtrips'||!t.parentId).map(([k,label])=>`<button data-action="tab" data-tab="${k}" class="${view.tab===k?'selected':''}">${label}</button>`).join('')}</div>${({packing:()=>packingPage(t,st),bags:()=>bagsPage(t),subtrips:()=>subtripPage(t),info:()=>infoPage(t)})[view.tab]()} `;}
function direction(){return `<div class="seg"><button class="${view.leg==='out'?'selected':''}" data-action="leg" data-leg="out">${ic('plane')} Utreise</button><button class="${view.leg==='return'?'selected':''}" data-action="leg" data-leg="return">${ic('refresh')} Hjemreise</button></div>`;}
function itemRow(t,e){const i=s.items.find(x=>x.id===e.itemId);if(!i)return '';const checked=(e.packedQty||0)>=e.qty;return `<div class="pack-line"><input class="check" type="checkbox" aria-label="${checked?'Fjern avkrysning for':'Marker pakket'} ${esc(i.name)}" data-action="pack" data-id="${e.itemId}" ${checked?'checked':''}>${itemThumb(i)}<div class="line-content"><strong>${esc(i.name)}</strong><small>${e.qty} stk. · ${esc(pname(i.ownerId))} ${e.packedQty>0&&!checked?'· '+e.packedQty+' pakket':''}</small></div><button class="icon-mini" data-action="edit-entry" data-id="${i.id}" title="Rediger / flytt">${ic('edit')}</button><button class="icon-mini danger-mini" data-action="delete-item" data-id="${i.id}" title="Fjern fra denne turen">${ic('trash')}</button></div>`;}
function packingPage(t,st){let e=entries(t,view.leg),q=view.term.toLowerCase();const included=e.filter(x=>{const i=s.items.find(i=>i.id===x.itemId);return i&&(!q||[i.name,i.notes,pname(i.ownerId),bagPath(t,view.leg,x.bagId)].join(' ').toLocaleLowerCase('nb-NO').includes(q))});const grouped=new Map();for(const row of included){const key=row.bagId||'none';if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(row)}let gr=[...grouped.entries()].sort((a,b)=>bagPath(t,view.leg,a[0]).localeCompare(bagPath(t,view.leg,b[0]),'nb'));
 return `<div class="selector-row">${direction()}<div class="actions">${btn('Legg til','add-menu','plus')}${t.parentId?btn('Hent fra hovedtur','import-parent','copy','secondary'):''}</div></div><div class="card" style="margin-bottom:17px"><div class="progress-top"><span>Kontrollert på ${view.leg==='out'?'utreise':'hjemreise'}</span><strong>${st.done} / ${st.total}</strong></div>${pbar(st.done,st.total)}<p class="progress-note">${Math.max(0,st.total-st.done)} stk. mangler pakkebekreftelse. Hver reiseretning har egen kontroll.</p></div><div class="search-field" style="margin-bottom:14px">${ic('search')}<input type="search" id="trip-search" placeholder="Søk i pakkelisten ..." value="${esc(view.term)}" aria-label="Søk i pakkelisten"></div><div id="pack-results">${gr.length?gr.map(([bid,rows])=>`<section class="pack-group"><div class="pack-group-title">${ic(bag(bid)?.type==='inner'?'folder':'backpack')}<h3>${esc(bagPath(t,view.leg,bid))}</h3><small>${rows.length} linjer</small></div><div class="pack-group-body">${rows.map(x=>itemRow(t,x)).join('')}</div></section>`).join(''):blank('Ingen gjenstander','Legg til en gjenstand eller hent et pakkesett.','','')}</div>${t.parentId&&view.leg==='return'?`<div class="hint">Gjenstander kjøpt på denne delreisen kan automatisk legges til hovedturens hjemreisekontroll. Registrer gaver og forbruk under «Endring på tur».</div>`:''}`;}
function bagTree(t,leg,parentId=null,depth=0){if(depth>8)return '';const rows=s.bagPositions.filter(x=>x.tripId===t.id&&x.leg===leg&&(x.parentBagId||null)===parentId);return rows.map(p=>{const b=bag(p.bagId);if(!b)return '';let count=entries(t,leg).filter(x=>x.bagId===p.bagId).length;return `<div class="${depth?'nested':''}"><div class="bag-tree-label">${ic(b.type==='inner'?'folder':'luggage')}<div class="grow"><strong>${esc(b.name)}</strong><div class="muted small">${esc(pname(b.ownerId))} · ${count} gjenstandslinjer</div></div>${parentId?`<label class="small nowrap" title="Mappen er lagt i ytterbagasjen"><input class="check" type="checkbox" style="width:20px;height:20px;vertical-align:middle" data-action="pack-bag" data-id="${b.id}" ${p.packed?'checked':''}> Pakket</label>`:''}<button class="icon-mini" data-action="edit-bag" data-id="${b.id}" title="Endre bagasjeplassering">${ic('edit')}</button><button class="icon-mini danger-mini" data-action="delete-bag" data-id="${b.id}" title="Fjern bagasje fra turen">${ic('trash')}</button></div>${entries(t,leg).filter(e=>e.bagId===b.id).map(e=>{const i=s.items.find(x=>x.id===e.itemId);return i?`<div class="simple-row" style="padding:7px 0 7px 30px"><span class="grow small">${esc(i.name)} · ${e.qty} stk.</span><button class="row-action" data-action="edit-entry" data-id="${i.id}" aria-label="Rediger ${esc(i.name)}">${ic('arrow')}</button><button class="icon-mini danger-mini" data-action="delete-item" data-id="${i.id}" aria-label="Fjern ${esc(i.name)}">${ic('trash')}</button></div>`:''}).join('')}${bagTree(t,leg,b.id,depth+1)}</div>`}).join('')};
function bagsPage(t){return `<div class="selector-row">${direction()}<div class="actions">${btn('Ny bagasje','new-bag','plus')}${btn('Hent lagret bagasje','apply-template','copy','secondary')}${t.parentId?btn('Hent bagasje','import-bags','copy','secondary'):''}</div></div><div class="card"><div class="card-head"><h2>Hvor ligger tingene?</h2><span class="tag">${tripBags(t,view.leg).length} bagasjeenheter</span></div>${tripBags(t,view.leg).length?bagTree(t,view.leg):blank('Ingen bagasje','Opprett en sekk, koffert eller innerbagasje.',btn('Ny bagasje','new-bag','plus'))}</div><p class="footer-note">En innerbag kan ligge i en annen bag. Flytt hele mappen eller én gjenstand uten å endre plasseringen på den andre reiseretningen.</p>`;}
function subtripPage(t){const subs=children(t.id).sort((a,b)=>(a.start||'').localeCompare(b.start||''));return `<div class="page-head"><div><h2>Delreiser</h2><div class="muted small">Separate pakkelister, felles gjenstandsidentitet.</div></div>${btn('Ny undertur','new-sub','plus','','data-id="'+t.id+'"')}</div><div class="card">${subs.length?subs.map(tripRow).join(''):blank('Ingen delreiser','Legg til Oslo-tur, hyttetur eller en annen del av reisen.')}</div>${s.events.some(x=>x.rootId===t.id)?`<section class="section-title"><h2>Endringer på hovedreisen</h2></section><div class="card">${s.events.filter(x=>x.rootId===t.id).slice(-8).reverse().map(logLine).join('')}</div>`:''}`;}
function infoPage(t){return `<div class="grid two"><div class="card"><div class="card-head"><h2>Turinformasjon</h2>${btn('Rediger tur / bilde','edit-trip','camera','secondary small','data-id="'+t.id+'"')}</div><p><strong>${esc(t.name)}</strong></p><p class="muted" style="margin-top:8px">${esc(period(t))}</p><p class="muted" style="margin-top:8px">${esc(t.destination||'Ingen destinasjon')}</p>${t.description?`<div class="line"></div><p class="small">${esc(t.description)}</p>`:''}<div class="line"></div><p class="subtle-label">Forsidebilde</p>${cover(t)?`<img src="${cover(t)}" class="photo-preview" alt="Forsidebilde">`:'<div class="hint">Ingen bilde valgt – Codex Nord-standard brukes.</div>'}</div><div class="card"><div class="card-head"><h2>Deltakere på turen</h2></div>${(t.participantIds||[]).map(pid=>`<div class="regular-row">${portrait(person(pid))}<span>${esc(pname(pid))}</span></div>`).join('')||'<p class="muted small">Ingen deltakere valgt.</p>'}<div class="line"></div>${btn('Rediger deltakere','edit-trip','edit','secondary','data-id="'+t.id+'"')}</div></div><div class="section-title"><h2>Turhandlinger</h2></div><div class="card"><div class="actions">${btn('Dupliser tur','duplicate-trip','copy','secondary','data-id="'+t.id+'"')}${btn('Slett tur','delete-trip','trash','danger','data-id="'+t.id+'"')}</div></div>`;}
function renderPeople(){return `${heading('Deltakere','Gjenbruk personer på alle turer.',btn('Ny deltaker','new-person','plus'))}<div class="card">${s.people.length?s.people.map(p=>`<div class="regular-row">${portrait(p)}<div class="grow"><strong>${esc(p.name)}</strong><div class="small muted">${s.trips.filter(t=>t.participantIds?.includes(p.id)).length} turer</div></div><button class="icon-mini" data-action="edit-person" data-id="${p.id}" aria-label="Rediger ${esc(p.name)}">${ic('edit')}</button></div>`).join(''):blank('Ingen deltakere','Legg til personer én gang og velg dem på nye turer.',btn('Ny deltaker','new-person','plus'))}</div>`;}
function renderThings(){
 const groupTemplate=b=>`<div class="library-bag"><div class="regular-row"> <div class="card-icon">${ic(b.type==='inner'?'folder':'backpack')}</div><div class="grow"><strong>${esc(b.name)}</strong><div class="muted small">${(b.setIds||[]).length} pakkesett · ${(b.entries||[]).length} løse gjenstander</div></div><button class="icon-mini" data-action="edit-template" data-id="${b.id}" title="Rediger bagasje">${ic('edit')}</button></div><div class="library-content">${(b.setIds||[]).map(sid=>{const x=s.sets.find(a=>a.id===sid);return x?`<div class="library-set">${ic('layers')} <b>${esc(x.name)}</b>${x.entries.map(e=>{let c=s.catalog.find(c=>c.id===e.catalogId);return c?`<div class="library-leaf">${itemThumb(c)}<span>${esc(c.name)} · ${e.qty} stk.</span></div>`:''}).join('')}</div>`:''}).join('')}${(b.entries||[]).map(e=>{const c=s.catalog.find(c=>c.id===e.catalogId);return c?`<div class="library-leaf">${itemThumb(c)}<span>${esc(c.name)} · ${e.qty} stk.</span></div>`:''}).join('')}${!(b.setIds||[]).length&&!(b.entries||[]).length?'<div class="muted small">Tom bagasje – kan fylles på en tur.</div>':''}</div></div>`;
 return `${heading('Mine ting','Bygg et bibliotek du kan hente inn på nye turer.')}<div class="stack"><section class="card"><div class="card-head"><div><h2>Bagasje</h2><p class="muted small">Gjenbruk bager alene, eller med pakkesett og gjenstander.</p></div>${btn('Ny bagasje','new-template','plus','secondary small')}</div>${s.bagTemplates.length?s.bagTemplates.map(groupTemplate).join(''):blank('Ingen lagret bagasje','Opprett en sekk, koffert eller mappe som kan gjenbrukes på nye turer.')}</section><section class="card"><div class="card-head"><h2>Pakkesett</h2>${btn('Nytt sett','new-set','plus','secondary small')}</div>${s.sets.length?s.sets.map(x=>`<div class="regular-row"><div class="card-icon">${ic('layers')}</div><div class="grow"><strong>${esc(x.name)}</strong><div class="small muted">${x.entries.length} gjenstander</div><div class="library-mini">${x.entries.slice(0,5).map(e=>esc(s.catalog.find(c=>c.id===e.catalogId)?.name||'')).filter(Boolean).join(' · ')}</div></div><button class="icon-mini" data-action="edit-set" data-id="${x.id}" title="Rediger pakkesett">${ic('edit')}</button></div>`).join(''):blank('Lag gjenbrukbare sett','For eksempel Elektronikksett, Toalettsaker og Skiutstyr.')}</section><section class="card"><div class="card-head"><h2>Gjenstander</h2>${btn('Ny gjenstand','new-catalog','plus','secondary small')}</div>${s.catalog.length?s.catalog.map(c=>`<div class="regular-row">${itemThumb(c)}<div class="grow"><strong>${esc(c.name)}</strong><div class="muted small">${esc(pname(c.ownerId))}</div></div><button class="icon-mini" data-action="edit-catalog" data-id="${c.id}" title="Rediger gjenstand">${ic('edit')}</button></div>`).join(''):blank('Ingen lagrede gjenstander','Registrer ting én gang og velg dem i pakkesett og bagasje.')}</section></div>`;
}

function renderSettings(){return `${heading('Innstillinger','Lokal lagring, sikkerhetskopi og testdata.') }<div class="grid two"><section class="card stack"><h2>Utseende og lagring</h2><div class="simple-row"><div class="grow">Codex Nord-tema</div>${btn(s.theme==='dark'?'Mørk':'Lys','theme',s.theme==='dark'?'moon':'sun','secondary small')}</div><div class="simple-row"><div class="grow">Sikkerhetskopi med bilder</div>${btn('Eksporter','export','download','secondary small')}</div><div class="simple-row"><div class="grow">Gjenopprett fra JSON</div>${btn('Importer','import','upload','secondary small')}</div><div class="hint">Data lagres i IndexedDB på enheten der appen åpnes. GitHub lagrer ikke pakkelistene dine, og ulike enheter synkroniseres ikke automatisk.</div></section><section class="card stack"><h2>Test og versjon</h2><p class="muted small">Codex Packit – GitHub testutgave 0.4, Codex Nord.</p>${btn('Opprett prøvetur','demo','plus','secondary')}${btn('Finn ting','navigate','search','secondary','data-page="search"')}<div class="hint">PWA: På iPhone åpner du GitHub Pages-adressen i Safari og velger «Legg til på Hjem-skjerm». Besøk appen på nett før du bruker den offline.</div></section></div>`;}
function logLine(e){let t=trip(e.tripId);return `<div class="log-entry">${ic(e.kind==='lost'?'alert':'refresh')}<span>${esc(e.message)}${t?' · '+esc(t.name):''}<br><small>${new Date(e.at).toLocaleString('nb-NO')}</small></span></div>`;}
function renderSearch(){const query=view.searchTerm.toLocaleLowerCase('nb-NO').trim(),t=trip(view.selectedRoot)||preferred();let matches=[];
 for(const r of s.legs){const i=s.items.find(x=>x.id===r.itemId),x=trip(r.tripId);if(!i||!x)continue;if(view.searchScope==='current'&&(!t||rootId(x)!==rootId(t)))continue;if(query&&![i.name,i.notes,x.name,pname(i.ownerId),bagPath(x,r.leg,r.bagId)].join(' ').toLocaleLowerCase('nb-NO').includes(query))continue;matches.push({r,i,x});}
 matches.sort((a,b)=>a.i.name.localeCompare(b.i.name,'nb')||a.x.name.localeCompare(b.x.name,'nb'));
 return `${heading('Finn ting','Søk etter hvor ting er planlagt eller bekreftet pakket.') }<div class="card stack"><div class="search-field">${ic('search')}<input id="global-search" type="search" placeholder="Søk: Garmin-lader, USB-C, koffert …" value="${esc(view.searchTerm)}" autofocus></div><div class="selector-row"><div class="seg"><button data-action="search-scope" data-scope="current" class="${view.searchScope==='current'?'selected':''}">Aktuell hovedtur</button><button data-action="search-scope" data-scope="all" class="${view.searchScope==='all'?'selected':''}">Alle turer / historikk</button></div></div>${matches.length?`<div class="muted small">${matches.length} treff på pakkeposter</div>${matches.slice(0,70).map(({r,i,x})=>`<div class="regular-row">${itemThumb(i)}<div class="grow"><strong>${esc(i.name)} · ${r.qty} stk.</strong><div class="small muted">${esc(x.name)} · ${r.leg==='out'?'Utreise':'Hjemreise'} · ${esc(pname(i.ownerId))}</div><div class="small" style="margin-top:5px">${ic('pin')} ${esc(bagPath(x,r.leg,r.bagId))} · <span class="${r.packedQty>=r.qty?'muted':''}">${r.packedQty>=r.qty?'Bekreftet pakket':'Planlagt, ikke bekreftet'}</span></div></div><button class="row-action" data-action="open-trip-leg" data-id="${x.id}" data-leg="${r.leg}">${ic('arrow')}</button></div>`).join('')}`:blank('Ingen treff','Prøv et annet navn, en annen bagasje eller søk i historikken.')}</div>`;}
const field=(label,name,value='',type='text',attrs='')=>`<div class="field"><label for="f_${name}">${label}</label><input id="f_${name}" type="${type}" name="${name}" value="${esc(value)}" ${attrs}></div>`;
const area=(label,name,value='')=>`<div class="field wide"><label for="f_${name}">${label}</label><textarea id="f_${name}" name="${name}" maxlength="600">${esc(value)}</textarea></div>`;
const select=(label,name,options,value='',extra='')=>`<div class="field"><label for="f_${name}">${label}</label><select id="f_${name}" name="${name}" ${extra}>${options.map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select></div>`;
const peopleOptions=(none='Ingen eier')=>[{value:'',label:none},...s.people.map(p=>({value:p.id,label:p.name}))];
const tripParticipants=t=>`<div class="field wide"><label>Deltakere</label>${s.people.length?`<div class="form-checks">${s.people.map(p=>`<label><input type="checkbox" name="participants" value="${p.id}" ${t?.participantIds?.includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div>`:`<p class="form-note">Opprett deltakere under «Deltakere» for å kunne velge dem her.</p>`}</div>`;
function showDialog(title,content,handler,{submit='Lagre',wide=false}={}){const d=$('#modal');d.innerHTML=`<header><h2>${esc(title)}</h2><button class="icon-btn" type="button" data-action="close-modal" aria-label="Lukk">${ic('x') }</button></header><form id="edit-form"><div class="modal-grid">${content}</div><div class="modal-actions"><button class="btn ghost" type="button" data-action="close-modal">Avbryt</button><button class="btn" type="submit">${esc(submit)}</button></div></form>`;d.showModal();d.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const f=ev.target,btn=f.querySelector('[type=submit]');btn.disabled=true;try{await handler(new FormData(f),f);d.close();render();}catch(err){toast(err.message||String(err),true);}finally{btn.disabled=false;}};}
function ask(title,message,yes,action){const d=$('#modal');d.innerHTML=`<header><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal">${ic('x')}</button></header><form method="dialog"><p style="padding:3px 0 15px;line-height:1.6">${esc(message)}</p><div class="modal-actions"><button class="btn secondary" value="cancel">Avbryt</button><button class="btn danger" value="ok">${esc(action||'Bekreft')}</button></div></form>`;d.showModal();d.querySelector('form').addEventListener('submit',e=>{if(e.submitter?.value==='ok'){Promise.resolve(yes()).then(()=>{d.close();render()}).catch(err=>toast(err.message,true));}}, {once:true});}
async function imageData(file,max=1500){if(!file||!file.size)return null;if(!file.type.startsWith('image/'))throw Error('Velg et bilde.');if(file.size>15*1024*1024)throw Error('Bildet kan ikke være større enn 15 MB.');const bitmap=await createImageBitmap(file),k=Math.min(1,max/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*k));canvas.height=Math.max(1,Math.round(bitmap.height*k));let ctx=canvas.getContext('2d');ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.8);}
function tripModal(t=null,parentId=null){const parent=t?.parentId||parentId||null;const parentTrip=parent?trip(parent):null;
 showDialog(t?'Rediger tur':parent?'Ny undertur':'Ny hovedtur',`${field('Navn *','name',t?.name||'','text','required maxlength="90" placeholder="Sommerferie 2027"')}${field('Destinasjon','destination',t?.destination||'','text','maxlength="100"')}${field('Avreise','start',t?.start||'','date')}${field('Hjemreise','end',t?.end||'','date')}${select('Reisefase','phase',[['planning','Planlegging'],['ongoing','Pågår'],['return','Hjemreise'],['done','Avsluttet']].map(([value,label])=>({value,label})),t?.phase||'planning')}${area('Beskrivelse / notater','description',t?.description||'')}${tripParticipants(t||{participantIds:parentTrip?.participantIds||[]})}<div class="field wide"><label for="f_cover">Forsidebilde (valgfritt)</label>${t&&cover(t)?`<img class="photo-preview" src="${cover(t)}" alt="Eksisterende forside">`:''}<input id="f_cover" type="file" name="cover" accept="image/*"><p class="form-note">Velg fra bildebiblioteket eller ta et bilde. Komprimeres og lagres offline. Delreiser kan arve hovedturens bilde.</p>${t?.cover?'<label class="form-note"><input type="checkbox" name="removeCover" value="yes"> Fjern eget forsidebilde</label>':''}</div>${select('Bildeutsnitt','coverY',[{value:'20',label:'Øvre del'},{value:'50',label:'Midten'},{value:'80',label:'Nedre del'}],String(t?.coverY??50))}`,
 async d=>{const name=String(d.get('name')||'').trim(),start=d.get('start')||'',end=d.get('end')||'';if(!name)throw Error('Turen må ha navn.');if(start&&end&&end<start)throw Error('Hjemreisedato kan ikke være før avreise.');if(parentTrip&&start&&parentTrip.start&&start<parentTrip.start)throw Error('Delreiseen starter før hovedturen.');if(parentTrip&&end&&parentTrip.end&&end>parentTrip.end)throw Error('Delreiseen slutter etter hovedturen.');const file=d.get('cover');let photo=file?.size?await imageData(file):undefined;let data={name,destination:d.get('destination')||'',start,end,phase:d.get('phase'),description:d.get('description')||'',participantIds:d.getAll('participants').map(String),coverY:Number(d.get('coverY'))};if(t){Object.assign(t,data);if(d.get('removeCover'))t.cover=null;if(photo)t.cover=photo;}else{let x={id:ID(),parentId:parent,cover:photo||null,createdAt:now(),...data};s.trips.push(x);view.tripId=x.id;view.page='trip';view.tab='packing';view.leg='out';}persist();toast(t?'Turen er oppdatert.':'Turen er opprettet.');}, {submit:t?'Lagre endringer':'Opprett tur'});
}
function personModal(id=null){const p=person(id);showDialog(p?'Rediger deltaker':'Ny deltaker',`${field('Navn *','name',p?.name||'','text','required maxlength="90"')}<div class="field wide"><label>Profilbilde (valgfritt)</label>${safeImg(p?.photo)?`<img class="person-photo-preview" src="${p.photo}" alt="Profilbilde">`:''}<input type="file" name="photo" accept="image/*">${safeImg(p?.photo)?'<label class="check-label"><input type="checkbox" name="removePhoto" value="yes"> Fjern bilde</label>':''}</div>`,async d=>{let name=String(d.get('name')||'').trim();if(!name)throw Error('Skriv inn navn.');let file=d.get('photo'),photo=file?.size?await imageData(file,650):undefined;if(p){p.name=name;if(d.get('removePhoto'))p.photo=null;if(photo)p.photo=photo;}else s.people.push({id:ID(),name,photo:photo||null});persist();toast('Deltaker lagret.');});}
function catalogModal(id=null){const c=s.catalog.find(x=>x.id===id);showDialog(c?'Rediger gjenstand':'Ny gjenstand',`${field('Navn *','name',c?.name||'','text','required maxlength="120"')}${select('Standard eier','ownerId',peopleOptions(),c?.ownerId||'')}${area('Notat','notes',c?.notes||'')}<div class="field wide"><label>Bilde (valgfritt)</label>${safeImg(c?.photo)?`<img class="photo-preview" src="${c.photo}" alt="Gjenstandsbilde">`:''}<input type="file" name="photo" accept="image/*">${safeImg(c?.photo)?'<label class="check-label"><input type="checkbox" name="removePhoto" value="yes"> Fjern bilde</label>':''}</div>`,async d=>{const name=String(d.get('name')||'').trim();if(!name)throw Error('Navn mangler.');let f=d.get('photo'),photo=f?.size?await imageData(f,900):undefined;const data={name,ownerId:d.get('ownerId')||'',notes:d.get('notes')||''};if(c){Object.assign(c,data);if(d.get('removePhoto'))c.photo=null;if(photo)c.photo=photo;}else s.catalog.push({id:ID(),...data,photo:photo||null});persist();toast('Gjenstand lagret.');});}

function setModal(id=null){const x=s.sets.find(z=>z.id===id);const opts=s.catalog.map(c=>({value:c.id,label:c.name}));showDialog(x?'Rediger pakkesett':'Nytt pakkesett',`${field('Navn på sett *','name',x?.name||'','text','required maxlength="100"')}<div class="field wide"><label>Velg gjenstander fra katalogen</label>${opts.length?`<div class="stack">${s.catalog.map(c=>{const existing=x?.entries.find(e=>e.catalogId===c.id);return `<div class="row between"><label class="row" style="font-weight:500"><input type="checkbox" name="catalog" value="${c.id}" ${existing?'checked':''}> ${esc(c.name)}</label><input type="number" aria-label="Antall ${esc(c.name)}" name="qty_${c.id}" value="${existing?.qty||1}" min="1" max="999" style="width:73px;padding:8px;background:var(--surface2);border:1px solid var(--border);border-radius:8px;color:var(--text)"></div>`}).join('')}</div>`:'<p class="form-note">Opprett først gjenstander i katalogen.</p>'}</div>`,d=>{let name=String(d.get('name')||'').trim();if(!name)throw Error('Skriv inn et navn.');let selected=d.getAll('catalog').map(String),entries=selected.map(k=>({catalogId:k,qty:Number(d.get('qty_'+k)||1)}));if(entries.some(e=>e.qty<1||e.qty>999||!Number.isInteger(e.qty)))throw Error('Antall må være mellom 1 og 999.');if(x)Object.assign(x,{name,entries});else s.sets.push({id:ID(),name,entries});persist();toast('Pakkesett lagret.');});}

function templateModal(id=null){const b=s.bagTemplates.find(x=>x.id===id),sets=s.sets||[],catalog=s.catalog||[];
 showDialog(b?'Rediger lagret bagasje':'Lagre ny bagasje',`${field('Navn *','name',b?.name||'','text','required maxlength="90"')}${select('Type','type',[{value:'outer',label:'Sekk / koffert'},{value:'inner',label:'Mappe / innerbagasje'}],b?.type||'outer')}${select('Standard eier','ownerId',peopleOptions(),b?.ownerId||'')}<div class="field wide"><label>Inkluder pakkesett</label>${sets.length?`<div class="option-list">${sets.map(x=>`<label class="option-check"><input type="checkbox" name="setIds" value="${x.id}" ${(b?.setIds||[]).includes(x.id)?'checked':''}><span>${esc(x.name)} (${x.entries.length} gjenstander)</span></label>`).join('')}</div>`:'<p class="form-note">Opprett først et pakkesett hvis bagasjen skal inneholde ett.</p>'}</div><div class="field wide"><label>Andre gjenstander i bagasjen</label>${catalog.length?`<div class="option-list">${catalog.map(c=>{let e=(b?.entries||[]).find(e=>e.catalogId===c.id);return `<div class="option-qty"><label class="option-check"><input type="checkbox" name="catalogIds" value="${c.id}" ${e?'checked':''}><span>${esc(c.name)}</span></label><input aria-label="Antall ${esc(c.name)}" type="number" name="qty_${c.id}" min="1" max="999" value="${e?.qty||1}"></div>`}).join('')}</div>`:'<p class="form-note">Gjenstander legges til under «Mine ting».</p>'}</div><div class="field wide"><p class="form-note">Bagasjen lagres som mal og kan gjenbrukes uten innhold eller med ferdige pakkesett. Endringer på en tur oppdaterer ikke malen.</p></div>`,d=>{let name=String(d.get('name')||'').trim();if(!name)throw Error('Navn mangler.');let entries=d.getAll('catalogIds').map(catalogId=>({catalogId:String(catalogId),qty:Number(d.get('qty_'+catalogId)||1)}));if(entries.some(e=>!Number.isInteger(e.qty)||e.qty<1||e.qty>999))throw Error('Antall må være 1–999.');const data={name,type:d.get('type'),ownerId:d.get('ownerId')||'',setIds:d.getAll('setIds').map(String),entries};if(b)Object.assign(b,data);else s.bagTemplates.push({id:ID(),...data});persist();toast('Bagasjemal lagret.');});}
function applyTemplate(){const t=trip(view.tripId),templates=s.bagTemplates;
 if(!templates.length){toast('Opprett først en bagasje under «Mine ting».',true);return;}
 showDialog('Hent lagret bagasje',`${select('Velg bagasje','templateId',[{value:'',label:'Velg bagasje'},...templates.map(b=>({value:b.id,label:b.name}))])}${select('Plasser inni','parentBagId',parentOptions(t,'out'))}<div class="field wide"><p class="form-note">Du kan hente inn en tom bag eller en med gjenstander og pakkesett. Bagasjen og innholdet legges til på begge reiseretninger.</p></div>`,d=>{const template=templates.find(x=>x.id===d.get('templateId'));if(!template)throw Error('Velg en lagret bagasje.');const parent=String(d.get('parentBagId')||'');const b={id:ID(),rootId:rootId(t),name:template.name,type:template.type||'outer',ownerId:template.ownerId||'',sourceTemplateId:template.id};s.bags.push(b);for(let l of ['out','return'])s.bagPositions.push({tripId:t.id,leg:l,bagId:b.id,parentBagId:parent||null,packed:false});let q=new Map();for(const sid of template.setIds||[]){const set=s.sets.find(x=>x.id===sid);for(const e of set?.entries||[])q.set(e.catalogId,Math.max(q.get(e.catalogId)||0,e.qty));}for(const e of template.entries||[])q.set(e.catalogId,Math.max(q.get(e.catalogId)||0,e.qty));let added=0,skipped=0;for(const [cid,qty] of q){const c=s.catalog.find(x=>x.id===cid);if(!c)continue;if(inventory(t).some(i=>i.sourceCatalogId===cid&&(entry(t,'out',i.id)||entry(t,'return',i.id)))){skipped++;continue;}const i={id:ID(),rootId:rootId(t),name:c.name,ownerId:c.ownerId||'',notes:c.notes||'',sourceCatalogId:cid,createdInTripId:t.id};s.items.push(i);for(const l of ['out','return'])rowUpsert(t,l,i.id,qty,b.id);added++;}persist();toast(`Bagasje hentet: ${added} gjenstander${skipped?', '+skipped+' duplikat(er) utelatt':''}.`);},{submit:'Hent bagasje'});
}
function removeItemFromTrip(t,iid){const ids=[t.id,...(!t.parentId?children(t.id).map(x=>x.id):[])];s.legs=s.legs.filter(x=>!(ids.includes(x.tripId)&&x.itemId===iid));if(!s.legs.some(x=>x.itemId===iid)){s.items=s.items.filter(i=>i.id!==iid);s.events=s.events.filter(x=>x.itemId!==iid);}persist();toast('Gjenstand fjernet fra turen.');}
function removeBagFromTrip(t,bid){const ids=[t.id,...(!t.parentId?children(t.id).map(x=>x.id):[])];for(const l of s.legs)if(ids.includes(l.tripId)&&l.bagId===bid){l.bagId='';l.packedQty=0;}for(const p of s.bagPositions)if(ids.includes(p.tripId)&&p.parentBagId===bid){p.parentBagId=null;p.packed=false;}s.bagPositions=s.bagPositions.filter(p=>!(ids.includes(p.tripId)&&p.bagId===bid));if(!s.bagPositions.some(x=>x.bagId===bid))s.bags=s.bags.filter(b=>b.id!==bid);persist();toast('Bagasje fjernet. Innholdet ligger nå uten bagasje.');}

function ensureBagPos(t,leg,bid){if(!placement(t,leg,bid))s.bagPositions.push({tripId:t.id,leg,bagId:bid,parentBagId:null,packed:false});}
function parentOptions(t,leg,exclude=null){let vals=[{value:'',label:'Ingen (hovedbagasje)'}];for(const b of tripBags(t,leg))if(b.id!==exclude&&!isDescendant(t,leg,b.id,exclude))vals.push({value:b.id,label:bagPath(t,leg,b.id)});return vals;}
function isDescendant(t,leg,bid,ancestor){if(!ancestor)return false;const visited=new Set();while(bid&&!visited.has(bid)){visited.add(bid);if(bid===ancestor)return true;bid=placement(t,leg,bid)?.parentBagId;}return false;}
function bagModal(id=null){const t=trip(view.tripId),b=bag(id),p=b?placement(t,view.leg,b.id):null;showDialog(b?'Plassering av bagasje':'Ny bagasje',`${b?`<div class="field wide"><div class="hint">Du endrer plassering for ${view.leg==='out'?'utreise':'hjemreise'}. Den andre reiseretningen påvirkes ikke.</div></div>`:''}${field('Navn *','name',b?.name||'','text','required maxlength="90"')}${select('Type','type',[{value:'outer',label:'Hovedbagasje (sekk/koffert)'},{value:'inner',label:'Innerbagasje (mappe/pakkepose)'}],b?.type||'outer')}${select('Eier','ownerId',peopleOptions(),b?.ownerId||'')}${select('Ligger i','parentBagId',parentOptions(t,view.leg,b?.id),p?.parentBagId||'')}${b?`<div class="field wide"><p class="form-note">Å endre navn og eier gjelder hele reisen. Plassering endres bare for denne reiseretningen.</p></div>`:''}`,
 d=>{let name=String(d.get('name')||'').trim(),par=String(d.get('parentBagId')||'');if(!name)throw Error('Navn mangler.');if(b){if(par&&isDescendant(t,view.leg,par,b.id))throw Error('En bag kan ikke plasseres i seg selv.');Object.assign(b,{name,type:d.get('type'),ownerId:d.get('ownerId')||''});p.parentBagId=par||null;p.packed=false;}else{let x={id:ID(),rootId:rootId(t),name,type:d.get('type'),ownerId:d.get('ownerId')||''};s.bags.push(x);for(const leg of ['out','return'])s.bagPositions.push({tripId:t.id,leg,bagId:x.id,parentBagId:leg===view.leg?par||null:null,packed:false});}persist();toast('Bagasje lagret.');});}
function itemOptions(t,leg){return [{value:'',label:'Uten bagasje (plasser senere)'},...tripBags(t,leg).map(b=>({value:b.id,label:bagPath(t,leg,b.id)}))];}
function rowUpsert(t,leg,itemId,qty,bagId){let r=entry(t,leg,itemId);if(r){r.qty=qty;r.bagId=bagId;r.packedQty=Math.min(r.packedQty||0,qty);r.updatedAt=now();}else s.legs.push({tripId:t.id,leg,itemId,qty,bagId:bagId||'',packedQty:0,updatedAt:now()});}
function itemModal(id=null){const t=trip(view.tripId),existing=id?entry(t,view.leg,id):null;let i=id?s.items.find(x=>x.id===id):null;const out=i?entry(t,'out',id):null,back=i?entry(t,'return',id):null;let plan=out&&back?'both':out?'out':'return';const defaultBag=tripBags(t,view.leg)[0]?.id||'';
 showDialog(i?'Rediger gjenstand':'Legg til gjenstand',`${field('Gjenstand *','name',i?.name||'','text','required maxlength="120"')}${field('Antall *','qty',existing?.qty||out?.qty||back?.qty||1,'number','required min="1" max="999" step="1"')}${select('Eier','ownerId',peopleOptions(),i?.ownerId||'')}${select('Reiseplan','travelPlan',[{value:'both',label:'Begge veier'},{value:'out',label:'Kun utreise'},{value:'return',label:'Kun hjemreise'}],i?plan:view.leg==='return'?'return':'both')}${select('Bagasje på utreise','outBag',itemOptions(t,'out'),out?.bagId||defaultBag)}${select('Bagasje på hjemreise','returnBag',itemOptions(t,'return'),back?.bagId||defaultBag)}${area('Notat','notes',i?.notes||'')}<div class="field wide"><label>Gjenstandsbilde (valgfritt)</label>${itemPhoto(i)?`<img class="photo-preview" src="${itemPhoto(i)}" alt="Gjenstandsbilde">`:''}<input type="file" name="photo" accept="image/*"></div>${t.parentId&&!i?`<div class="field wide"><label class="row"><input type="checkbox" name="addParentReturn" value="yes" checked> Legg også til på hovedturens hjemreise</label><span class="form-note">Brukes ved nye innkjøp eller ting du får under delreisen.</span></div>`:''}`,
 async d=>{const name=String(d.get('name')||'').trim(),qty=Number(d.get('qty')),travel=d.get('travelPlan');const f=d.get('photo'),newPhoto=f?.size?await imageData(f,900):undefined;if(!name)throw Error('Navn mangler.');if(!Number.isInteger(qty)||qty<1||qty>999)throw Error('Antall må være mellom 1 og 999.');if(!i){i={id:ID(),rootId:rootId(t),name,ownerId:d.get('ownerId')||'',notes:d.get('notes')||'',sourceCatalogId:null,createdInTripId:t.id};s.items.push(i);}else Object.assign(i,{name,ownerId:d.get('ownerId')||'',notes:d.get('notes')||''});if(newPhoto)i.photo=newPhoto;
  for(const [leg,bid] of [['out',d.get('outBag')],['return',d.get('returnBag')]]){if(travel==='both'||travel===(leg==='out'?'out':'return')){rowUpsert(t,leg,i.id,qty,String(bid||''));}else s.legs=s.legs.filter(x=>!(x.tripId===t.id&&x.leg===leg&&x.itemId===i.id));}
  if(t.parentId&&!id&&d.get('addParentReturn')){const r=root(t);rowUpsert(r,'return',i.id,qty,'');s.events.push({id:ID(),rootId:r.id,tripId:t.id,itemId:i.id,kind:'purchase',qty,at:now(),message:`${name} (${qty} stk.) lagt til på hovedturens hjemreise`});}
  persist();toast('Gjenstand lagret.');}, {submit:i?'Lagre gjenstand':'Legg til gjenstand'});
}
function moveModal(iid){const t=trip(view.tripId),r=entry(t,view.leg,iid),i=s.items.find(x=>x.id===iid);if(!r||!i)return;showDialog('Flytt / kontroller gjenstand',`<div class="field wide"><div class="hint"><strong>${esc(i.name)}</strong> · ${view.leg==='out'?'Utreise':'Hjemreise'}<br>Gjenstanden forblir den samme, men kan ligge et annet sted.</div></div>${select('Bagasjeplassering', 'bagId',itemOptions(t,view.leg),r.bagId)}${field('Antall med på denne etappen','qty',r.qty,'number','min="1" max="999" required step="1"')}${field('Antall bekreftet pakket','packedQty',r.packedQty||0,'number','min="0" max="999" required step="1"')}<div class="field wide"><p class="form-note">Hvis du flytter noe som allerede er merket pakket, nullstilles kontrollen og må bekreftes på nytt.</p></div>`,d=>{let n=Number(d.get('qty')),packed=Number(d.get('packedQty')),newbag=d.get('bagId')||'';if(!Number.isInteger(n)||n<1||n>999||!Number.isInteger(packed)||packed<0||packed>n)throw Error('Kontroller antallet.');let moved=newbag!==r.bagId;r.bagId=newbag;r.qty=n;r.packedQty=moved?0:packed;r.updatedAt=now();persist();toast(moved?'Flyttet. Bekreft pakkingen på nytt.':'Pakkekontroll oppdatert.');},{submit:'Lagre plassering'});}
function optionsDialog(title,rows){let d=$('#modal');d.innerHTML=`<header><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Lukk">${ic('x')}</button></header><div style="padding:15px 22px 23px">${rows.map(x=>`<button class="nav-link" style="color:var(--text)" data-action="${x.action}" ${x.extra||''}>${ic(x.icon||'plus')}<span style="display:block">${esc(x.label)}</span>${ic('arrow')}</button>`).join('')}</div>`;d.showModal()}
function menuAdd(){const t=trip(view.tripId);optionsDialog('Legg til på '+t.name,[{action:'new-item',label:'Ny gjenstand',icon:'package'},{action:'apply-set',label:'Hent et pakkesett',icon:'layers'},{action:'apply-template',label:'Hent lagret bagasje',icon:'backpack'},{action:'new-bag',label:'Ny bagasje / innerbag',icon:'luggage'},{action:'edit-trip',label:'Legg til deltaker',icon:'users',extra:`data-id="${t.id}"`},...(t.parentId?[{action:'import-parent',label:'Hent fra hovedturen',icon:'copy'},{action:'record-event',label:'Endring på tur (gave / forbruk / tap)',icon:'refresh'}]:[])]);}
function importParent(){const t=trip(view.tripId);if(!t?.parentId)return;let avail=inventory(t).filter(i=>!entry(t,'out',i.id)&&!entry(t,'return',i.id));showDialog('Hent fra hovedturen',`<div class="field wide"><div class="hint">Gjenstandene får samme ID på både hovedtur og undertur. Ting som blir igjen på basen, legges ikke automatisk til.</div></div>${avail.length?`<div class="field wide"><label>Velg gjenstander</label><div class="stack">${avail.map(i=>`<label class="option-check"><input type="checkbox" name="items" value="${i.id}"> ${esc(i.name)} · ${esc(pname(i.ownerId))}</label>`).join('')}</div></div>`:'<div class="field wide"><p class="form-note">Alle tilgjengelige gjenstander er allerede lagt til.</p></div>'}`,d=>{let ids=d.getAll('items').map(String);for(const id of ids){let i=s.items.find(x=>x.id===id),r=entry(root(t),'out',id)||entry(root(t),'return',id),qty=r?.qty||1;rowUpsert(t,'out',i.id,qty,'');rowUpsert(t,'return',i.id,qty,'');}persist();toast(`${ids.length} gjenstander hentet.`);},{submit:'Hent valgte'});}
function importBags(){const t=trip(view.tripId);if(!t?.parentId)return;const available=rBags(t).filter(b=>!placement(t,'out',b.id)&&!placement(t,'return',b.id));showDialog('Hent bagasje fra hovedtur',`<div class="field wide"><p class="form-note">Hent eksisterende bagasje uten å duplisere den. Plasseringen kan endres på delreisen.</p>${available.length?available.map(b=>`<label class="option-check"><input type="checkbox" name="bags" value="${b.id}"> ${esc(b.name)} · ${esc(pname(b.ownerId))}</label>`).join(''):'<p class="form-note">Ingen flere bagasjeenheter å hente.</p>'}</div>`,d=>{let ids=d.getAll('bags');for(const bid of ids)for(const l of ['out','return'])ensureBagPos(t,l,bid);persist();toast('Bagasje tilgjengelig på delreisen.');},{submit:'Hent valgte'});}
function applySet(){const t=trip(view.tripId);showDialog('Hent pakkesett',`${select('Velg sett','setId',[{value:'',label:'Velg pakkesett'},...s.sets.map(x=>({value:x.id,label:`${x.name} (${x.entries.length} gjenstander)`}))])}${select('Plasser gjenstander i','bagId',itemOptions(t,'out'))}<div class="field wide"><div class="hint">Settet kopieres inn som pakkeposter, mens selve standardsettet beholdes uendret. Eksisterende gjenstander fra samme katalog hoppes over for å unngå dobbeltregistrering.</div></div>`,d=>{let x=s.sets.find(x=>x.id===d.get('setId'));if(!x)throw Error('Velg et pakkesett.');let added=0,skipped=0,bagId=String(d.get('bagId')||'');for(const rec of x.entries){let c=s.catalog.find(c=>c.id===rec.catalogId);if(!c)continue;if(inventory(t).some(i=>i.sourceCatalogId===c.id&&(entry(t,'out',i.id)||entry(t,'return',i.id)))){skipped++;continue;}let item={id:ID(),rootId:rootId(t),name:c.name,ownerId:c.ownerId||'',notes:c.notes||'',sourceCatalogId:c.id,sourceSetId:x.id,createdInTripId:t.id};s.items.push(item);rowUpsert(t,'out',item.id,rec.qty,bagId);rowUpsert(t,'return',item.id,rec.qty,bagId);added++;}persist();toast(`${added} lagt til${skipped?`, ${skipped} hoppet over (duplikater)`:''}.`);},{submit:'Hent pakkesett'});}
function eventModal(){const t=trip(view.tripId);if(!t.parentId){toast('Registrer endringen på en undertur.',true);return;}let options=inventory(t).filter(i=>entry(t,'out',i.id)||entry(t,'return',i.id)).map(i=>({value:i.id,label:i.name}));showDialog('Registrer endring på tur',`${select('Gjenstand','itemId',options)}${select('Hendelse','kind',[{value:'gift',label:'Gitt bort / etterlatt med vilje'},{value:'used',label:'Brukt opp'},{value:'lost',label:'Mistet / usikker plassering'}])}${field('Antall','qty',1,'number','required min="1" max="999" step="1"')}<div class="field wide"><div class="hint">Gaver og forbruk trekkes fra forventet hjemreise på hovedturen. Mistet gjenstand gir varsel, men fjernes ikke automatisk.</div></div>`,d=>{const itemId=String(d.get('itemId')||''),i=s.items.find(x=>x.id===itemId),qty=Number(d.get('qty')),kind=d.get('kind');if(!i)throw Error('Velg gjenstand.');if(!Number.isInteger(qty)||qty<1||qty>999)throw Error('Antall er ugyldig.');let r=entry(root(t),'return',itemId),local=entry(t,'return',itemId);if(kind!=='lost'){if(!r||r.qty<qty)throw Error('Antallet overstiger hovedturens forventede hjemreise.');r.qty-=qty;r.packedQty=Math.min(r.packedQty,r.qty);if(!r.qty)s.legs=s.legs.filter(x=>x!==r);if(local){local.qty=Math.max(0,local.qty-qty);local.packedQty=Math.min(local.packedQty,local.qty);if(!local.qty)s.legs=s.legs.filter(x=>x!==local);}}let what={gift:'gitt bort / etterlatt',used:'brukt opp',lost:'registrert mistet / uavklart'}[kind];s.events.push({id:ID(),tripId:t.id,rootId:rootId(t),itemId,kind,qty,at:now(),message:`${i.name}: ${qty} stk. ${what}`});persist();toast('Endringen er registrert.');},{submit:'Registrer endring'});}
function demo(){let name='Sommerferie 2027';if(s.trips.some(t=>t.name===name))name='Testtur '+new Date().toLocaleDateString('nb-NO');let a={id:ID(),name:'Meg'},b={id:ID(),name:'Anna'};if(!s.people.some(p=>p.name==='Meg'))s.people.push(a);else a=s.people.find(p=>p.name==='Meg');if(!s.people.some(p=>p.name==='Anna'))s.people.push(b);else b=s.people.find(p=>p.name==='Anna');
 const start=new Date();start.setDate(start.getDate()+14);const end=new Date(start);end.setDate(end.getDate()+18);const yyyy=d=>d.toISOString().slice(0,10);
 const main={id:ID(),parentId:null,name,destination:'Norge',start:yyyy(start),end:yyyy(end),phase:'planning',cover:null,coverY:50,description:'Prøvetur med hovedtur, undertur, bagasje og retursjekk.',participantIds:[a.id,b.id]},childStart=new Date(start);childStart.setDate(start.getDate()+3);const childEnd=new Date(start);childEnd.setDate(start.getDate()+6);const sub={id:ID(),parentId:main.id,name:'Oslo-tur',destination:'Oslo',start:yyyy(childStart),end:yyyy(childEnd),phase:'planning',cover:null,coverY:50,participantIds:[a.id,b.id],description:''};s.trips.push(main,sub);
 const pack={id:ID(),rootId:main.id,name:'Min ryggsekk',type:'outer',ownerId:a.id},anna={id:ID(),rootId:main.id,name:'Annas sekk',type:'outer',ownerId:b.id},electro={id:ID(),rootId:main.id,name:'Elektronikkmappe',type:'inner',ownerId:a.id};s.bags.push(pack,anna,electro);
 for(const tr of [main,sub])for(const dir of ['out','return'])for(const bg of [pack,anna,electro])s.bagPositions.push({tripId:tr.id,leg:dir,bagId:bg.id,parentBagId:bg.id===electro.id?pack.id:null,packed:false});
 for(const [nm,q,owner,op,ret,plan] of [['Garmin-lader',1,a.id,electro.id,anna.id,'both'],['USB-C-kabel',2,a.id,electro.id,electro.id,'both'],['Powerbank',1,a.id,electro.id,electro.id,'both'],['Gave til vertskap',1,a.id,pack.id,'','out'],['Tannbørste',1,b.id,anna.id,anna.id,'both']]){let i={id:ID(),rootId:main.id,name:nm,ownerId:owner,notes:'',createdInTripId:main.id};s.items.push(i);if(plan!=='return')rowUpsert(main,'out',i.id,q,op);if(plan!=='out')rowUpsert(main,'return',i.id,q,ret);if(nm==='Garmin-lader'||nm==='USB-C-kabel'){rowUpsert(sub,'out',i.id,q,op);rowUpsert(sub,'return',i.id,q,nm==='Garmin-lader'?anna.id:op);}}
 let c={id:ID(),name:'Garmin-lader',ownerId:a.id,notes:''};if(!s.catalog.some(x=>x.name===c.name))s.catalog.push(c);let e={id:ID(),name:'USB-C-kabel',ownerId:a.id,notes:''};if(!s.catalog.some(x=>x.name===e.name))s.catalog.push(e);
 s.sets.push({id:ID(),name:'Elektronikksett (eksempel)',entries:s.catalog.filter(x=>['Garmin-lader','USB-C-kabel'].includes(x.name)).map(x=>({catalogId:x.id,qty:x.name==='USB-C-kabel'?2:1}))});view.tripId=main.id;view.page='overview';persist();toast('Prøvetur opprettet.');}
function exportBackup(){const data={format:'codex-packit-backup',schemaVersion:4,exportedAt:now(),state:s},blob=new Blob([JSON.stringify(data)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Codex-Packit-backup-${now().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Sikkerhetskopi er eksportert.');}
function legacyToV3(old){if(!old||!Array.isArray(old.trips)||!Array.isArray(old.items))throw Error('Ukjent sikkerhetskopi.');const n=initial(),tripMap=new Map(),bagMap=new Map(),personMap=new Map();for(const t of old.trips){let x={id:t.id||ID(),parentId:null,name:String(t.name||'Tur'),destination:t.destination||'',start:t.startDate||t.start||'',end:t.endDate||t.end||'',phase:'planning',description:t.notes||'',cover:null,coverY:50,participantIds:[]};n.trips.push(x);tripMap.set(t.id,x);}for(const p of old.people||[]){let x={id:p.id||ID(),name:p.name||'Deltaker'};n.people.push(x);personMap.set(p.id,x);if(tripMap.has(p.tripId))tripMap.get(p.tripId).participantIds.push(x.id);}
 for(const b of old.bags||[]){let t=tripMap.get(b.tripId);if(!t)continue;let x={id:b.id||ID(),rootId:t.id,name:b.name||'Bagasje',type:'outer',ownerId:b.ownerId||''};n.bags.push(x);bagMap.set(b.id,x);for(const leg of ['out','return'])n.bagPositions.push({tripId:t.id,leg,bagId:x.id,parentBagId:null,packed:false});}
 for(const i of old.items){let t=tripMap.get(i.tripId);if(!t)continue;let x={id:i.id||ID(),rootId:t.id,name:i.name||'Gjenstand',ownerId:i.ownerId||'',notes:i.notes||'',createdInTripId:t.id};n.items.push(x);let plan=i.travelPlan||(i.newOnTrip?'return':'both'),bagId=bagMap.get(i.bagId)?.id||'',qty=Math.max(1,Number(i.qty)||1);for(const leg of ['out','return'])if(plan==='both'||plan===(leg==='out'?'out':'return'))n.legs.push({tripId:t.id,leg,itemId:x.id,qty,bagId,packedQty:i[leg==='out'?'outPacked':'returnPacked']?qty:0,updatedAt:now()});}return n;}
function upgradeState(data){data.bagTemplates=Array.isArray(data.bagTemplates)?data.bagTemplates:[];data.schemaVersion=4;return data;}
function validateBackup(obj){if(!obj||obj.format!=='codex-packit-backup'||!obj.state)throw Error('Ukjent Packit-sikkerhetskopi.');let data=[3,4].includes(obj.schemaVersion)?upgradeState(obj.state):upgradeState(legacyToV3(obj.state));if(!['trips','people','catalog','sets','bags','bagPositions','items','legs','events'].every(k=>Array.isArray(data[k])))throw Error('Sikkerhetskopien mangler nødvendige data.');if(data.trips.length>2000||data.items.length>100000)throw Error('Sikkerhetskopien er uvanlig stor.');for(const t of data.trips){if(!t.id||!t.name||t.cover&&!safeImg(t.cover))throw Error('Ugyldige turdata eller bilde i sikkerhetskopien.');}for(const v of [...data.people,...data.catalog,...data.items])if(v.photo&&!safeImg(v.photo))throw Error('Ugyldig bilde i sikkerhetskopien.');for(const r of data.legs)if(!r.tripId||!r.itemId||!['out','return'].includes(r.leg)||!Number.isInteger(r.qty)||r.qty<1||r.qty>99999)throw Error('Ugyldige pakkeposter.');data.schemaVersion=4;return data;}
async function importBackup(file){if(!file)return;if(file.size>100*1024*1024)throw Error('Sikkerhetskopien kan ikke være større enn 100 MB.');let raw=JSON.parse(await file.text()),data=validateBackup(raw);ask('Gjenopprett sikkerhetskopi?',`Dette vil erstatte dataene på denne enheten med ${data.trips.length} turer og ${data.items.length} gjenstander. Fortsette?`,async()=>{await writeQueue;s=data;setTheme(s.theme||'dark');persist();view.page='overview';view.tripId=null;toast('Sikkerhetskopi gjenopprettet.');},'Gjenopprett');}
function deleteTrip(t){const ids=[t.id,...children(t.id).map(x=>x.id)],r=rootId(t);s.trips=s.trips.filter(x=>!ids.includes(x.id));s.legs=s.legs.filter(x=>!ids.includes(x.tripId));s.bagPositions=s.bagPositions.filter(x=>!ids.includes(x.tripId));s.events=s.events.filter(x=>!ids.includes(x.tripId));if(!t.parentId){s.items=s.items.filter(x=>x.rootId!==r);s.bags=s.bags.filter(x=>x.rootId!==r);s.events=s.events.filter(x=>x.rootId!==r);}view.page='trips';view.tripId=null;persist();}
function duplicateTrip(t){
 const copy={...structuredClone(t),id:ID(),name:t.name+' (kopi)',phase:'planning',createdAt:now()};
 s.trips.push(copy);
 if(t.parentId){
  for(const row of s.legs.filter(x=>x.tripId===t.id))s.legs.push({...row,tripId:copy.id,packedQty:0});
  for(const pos of s.bagPositions.filter(x=>x.tripId===t.id))s.bagPositions.push({...pos,tripId:copy.id,packed:false});
 }else{
  const bagMap=new Map(),itemMap=new Map();
  for(const old of s.bags.filter(x=>x.rootId===t.id)){
   const newid=ID();bagMap.set(old.id,newid);s.bags.push({...structuredClone(old),id:newid,rootId:copy.id});
  }
  for(const old of s.items.filter(x=>x.rootId===t.id)){
   const newid=ID();itemMap.set(old.id,newid);s.items.push({...structuredClone(old),id:newid,rootId:copy.id,createdInTripId:copy.id});
  }
  for(const row of s.legs.filter(x=>x.tripId===t.id)){
   s.legs.push({...row,tripId:copy.id,itemId:itemMap.get(row.itemId),bagId:bagMap.get(row.bagId)||'',packedQty:0});
  }
  for(const pos of s.bagPositions.filter(x=>x.tripId===t.id)){
   s.bagPositions.push({...pos,tripId:copy.id,bagId:bagMap.get(pos.bagId),parentBagId:bagMap.get(pos.parentBagId)||null,packed:false});
  }
 }
 view.tripId=copy.id;view.page='trip';view.tab='packing';view.leg='out';persist();toast('Tur kopiert.');
}
function handle(action,btn){const id=btn.dataset.id;if(action!=='close-modal'&&$('#modal').open&&!['new-item','new-bag','apply-set','import-parent','edit-trip','record-event'].includes(action))$('#modal').close();
 switch(action){case 'navigate':go(btn.dataset.page);break;case 'open-trip':go('trip',id);break;case 'open-trip-leg':go('trip',id);view.leg=btn.dataset.leg;render();break;case 'tab':view.tab=btn.dataset.tab;render();break;case 'leg':view.leg=btn.dataset.leg;view.term='';render();break;case 'theme':setTheme(s.theme==='dark'?'light':'dark');persist();render();break;
 case 'new-trip':tripModal();break;case 'new-sub':tripModal(null,id||view.tripId);break;case 'edit-trip':$('#modal').close();tripModal(trip(id));break;case 'new-person':personModal();break;case 'edit-person':personModal(id);break;case 'new-catalog':catalogModal();break;case 'edit-catalog':catalogModal(id);break;case 'new-template':templateModal();break;case 'edit-template':templateModal(id);break;case 'new-set':setModal();break;case 'edit-set':setModal(id);break;
 case 'add-menu':menuAdd();break;case 'new-item':$('#modal').close();itemModal();break;case 'edit-entry':moveModal(id);break;case 'new-bag':$('#modal').close();bagModal();break;case 'edit-bag':bagModal(id);break;case 'apply-set':$('#modal').close();applySet();break;case 'apply-template':$('#modal').close();applyTemplate();break;case 'import-parent':$('#modal').close();importParent();break;case 'import-bags':importBags();break;case 'record-event':$('#modal').close();eventModal();break;
 case 'delete-item':{const t=trip(view.tripId),i=s.items.find(x=>x.id===id);ask('Fjern gjenstand?',`Fjerne ${i?.name||'gjenstanden'} fra ${t.name}${t.parentId?'':' og tilhørende delreiser'}? Dette påvirker ikke gjenstandskatalogen.`,()=>removeItemFromTrip(t,id),'Fjern');break;}case 'delete-bag':{const t=trip(view.tripId),b=bag(id);ask('Fjern bagasje?',`Fjerne ${b?.name||'bagasjen'} fra denne turen${t.parentId?'':' og delreisene'}? Innhold flyttes til «Uten bagasje» og må kontrolleres på nytt.`,()=>removeBagFromTrip(t,id),'Fjern');break;}case 'pack':{const t=trip(view.tripId),r=entry(t,view.leg,id);if(!r)return;r.packedQty=btn.checked?r.qty:0;r.updatedAt=now();persist();render();break;}
 case 'pack-bag':{const t=trip(view.tripId),p=placement(t,view.leg,id);if(!p)return;p.packed=btn.checked;persist();render();break;}
 case 'export':exportBackup();break;case 'import':$('#backup-file').click();break;case 'demo':demo();render();break;case 'delete-trip':{const t=trip(id);ask('Slette tur?',`Vil du slette ${t.name}${t.parentId?'':' og alle delreisene'}? Dette kan ikke angres uten en sikkerhetskopi.`,()=>deleteTrip(t),'Slett tur');break;}
 case 'duplicate-trip':{const t=trip(id);ask('Kopiere tur?',`Opprett en kopi av ${t.name} med nye, ikke-avkryssede pakkelister?`,()=>duplicateTrip(t),'Kopier');break;}
 case 'close-modal':$('#modal').close();break;default:console.warn('ukjent handling',action);
 }}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn||btn.matches('input'))return;try{handle(btn.dataset.action,btn)}catch(err){console.error(err);toast(err.message||'En feil oppstod.',true)}});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('input[type=checkbox][data-action]'))try{handle(el.dataset.action,el)}catch(err){toast(err.message,true)}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='trip-search'){view.term=el.value;const tmp=document.createElement('div');tmp.innerHTML=packingPage(trip(view.tripId),stats(trip(view.tripId),view.leg));const x=tmp.querySelector('#pack-results');if(x)$('#pack-results').innerHTML=x.innerHTML;}else if(el.id==='global-search'){const start=el.selectionStart,end=el.selectionEnd;view.searchTerm=el.value;$('#main').innerHTML=renderSearch();const fresh=$('#global-search');fresh.focus();try{fresh.setSelectionRange(start,end);}catch{}}});
$('#backup-file').addEventListener('change',async e=>{try{await importBackup(e.target.files[0]);}catch(err){toast(err.message||'Import feilet.',true);}e.target.value='';});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
async function init(){try{const stored=await load();if(stored){if([3,4].includes(stored.schemaVersion)&&Array.isArray(stored.trips))s=upgradeState(stored);else if([1,2].includes(stored.schemaVersion))s=upgradeState(legacyToV3(stored));else throw Error('Ukjent databaseversjon.');}setTheme(s.theme||'dark');render();if(!stored)persist();if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(console.warn);}catch(err){console.error(err);$('#main').innerHTML=blank('Kunne ikke starte Packit',esc(err.message)+'. Sjekk lagringstillatelser i nettleseren.');toast('Databasefeil: '+err.message,true);}}
init();
